import {
  ROLES,
  emailError,
  errorMessages,
  nameLengthError,
  normalizeEmail,
  normalizeName,
  roleError,
} from '../userValidation.js';

const INVITABLE_ROLES = ROLES.filter((role) => role !== 'owner');

export function inviteUser(store, request) {
  const body = request.body ?? {};
  const email = normalizeEmail(body.email);
  const name = normalizeName(body.name);
  const role = body.role;

  // The invitee fills in their name when they accept, so an empty name is fine here.
  const messages = errorMessages(emailError(email), nameLengthError(name), inviteRoleError(role));
  if (messages.length > 0) {
    return validationFailed(messages);
  }
  if (store.findUserByEmail(email) || store.findInvitationByEmail(email)) {
    return conflict('email already in use');
  }
  return created(store.addInvitation({ email, name, role }));
}

function inviteRoleError(role) {
  return role === undefined ? 'role is required' : roleError(role, INVITABLE_ROLES);
}

