import { conflict, notFound, ok, validationFailed } from '../response.js';
import { emailError, nameError, normalizeEmail, normalizeName, roleError } from '../userValidation.js';

const FIELD_RULES = [
  { field: 'email', normalize: normalizeEmail, error: emailError },
  { field: 'name', normalize: normalizeName, error: nameError },
  { field: 'role', normalize: (role) => role, error: roleError },
];

export function updateUser(store, request) {
  const user = store.getUser(Number(request.params.id));
  if (!user) {
    return notFound('user not found');
  }

  const body = request.body ?? {};
  const messages = [];
  const changes = {};
  for (const { field, normalize, error } of FIELD_RULES) {
    if (body[field] === undefined) {
      continue;
    }
    const value = normalize(body[field]);
    const message = error(value);
    if (message === null) {
      changes[field] = value;
    } else {
      messages.push(message);
    }
  }

  if (messages.length > 0) {
    return validationFailed(messages);
  }
  if (Object.keys(changes).length === 0) {
    return validationFailed(['no fields to update']);
  }

  const owner = changes.email && store.findUserByEmail(changes.email);
  if (owner && owner.id !== user.id) {
    return conflict('email already in use');
  }
  return ok(store.updateUser(user.id, changes));
}

